WITH base AS (SELECT *, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee FROM orders WHERE (amount BETWEEN 410 AND 770 AND order_date >= '2023-08-04') OR amount BETWEEN 840 AND 1390), order_month_summary AS (SELECT DATE_TRUNC('MONTH', order_date) AS order_month, SUM(greatest_discount_shipping_fee) AS total_greatest_discount_shipping_fee FROM base GROUP BY DATE_TRUNC('MONTH', order_date)) SELECT * FROM order_month_summary WHERE total_greatest_discount_shipping_fee < 300 ORDER BY order_month;
